mapper.select:
SELECT resource_ref FROM audit_event a WHERE subject_id=#{userId} AND action=#{eventType} AND result='SUCCESS'
  AND project_id <=> #{projectId} AND schema_version='1.0.0' AND schema_manifest_sha256=#{manifest}
  AND created_by=#{userId} AND classification=#{classification} AND request_id=#{requestId} AND trace_id=#{requestId}
  AND JSON_UNQUOTE(JSON_EXTRACT(resource_ref,'$.operation_id'))=#{operationId}
